// parses "4–8" or "4-8" or "6" -> returns the higher bound (for subtotal estimate)
function parseQtyMax(qty) {
  const nums = String(qty).match(/[\d.,]+/g);
  if (!nums || !nums.length) return 1;
  const parsed = nums.map((n) => parseFloat(n.replace(",", ".")));
  return Math.max(...parsed);
}
function isRange(qty) {
  return /[–-]/.test(String(qty)) && String(qty).match(/[\d.,]+/g)?.length > 1;
}

// Divide uma faixa "4–8" em [4, 8]. Um valor único "6" vira [6, 6].
function splitQtyRange(qty) {
  const nums = String(qty).match(/[\d.,]+/g);
  if (!nums || !nums.length) return [0, 0];
  const parsed = nums.map((n) => parseFloat(n.replace(",", ".")));
  if (parsed.length === 1) return [parsed[0], parsed[0]];
  return [parsed[0], parsed[parsed.length - 1]];
}
// planKey "planInicial" usa o primeiro número da faixa; "planAvancado" usa o segundo.
function qtyForPlan(qty, planKey) {
  const [first, second] = splitQtyRange(qty);
  return planKey === "planInicial" ? first : second;
}
function formatQtyNumber(n) {
  const rounded = Math.round(n * 100) / 100;
  return Number.isInteger(rounded) ? String(rounded) : String(rounded).replace(".", ",");
}

/* ---------------------------------------------------------------
   PDF GENERATION (loads jsPDF + html2canvas from CDN on demand)
--------------------------------------------------------------- */
function loadScriptWithTimeout(src, timeoutMs = 9000) {
  return new Promise((resolve, reject) => {
    let settled = false;
    const timer = setTimeout(() => {
      if (!settled) { settled = true; reject(new Error(`Tempo esgotado ao carregar ${src}`)); }
    }, timeoutMs);
    const existing = document.querySelector(`script[data-cc-src="${src}"]`);
    if (existing) {
      clearTimeout(timer);
      settled = true;
      resolve();
      return;
    }
    const s = document.createElement("script");
    s.src = src;
    s.dataset.ccSrc = src;
    s.onload = () => { if (!settled) { settled = true; clearTimeout(timer); resolve(); } };
    s.onerror = () => { if (!settled) { settled = true; clearTimeout(timer); reject(new Error(`Falha de rede ao carregar ${src}`)); } };
    document.head.appendChild(s);
  });
}

async function ensurePdfLibs() {
  if (!window.html2canvas) {
    await loadScriptWithTimeout("https://cdnjs.cloudflare.com/ajax/libs/html2canvas/1.4.1/html2canvas.min.js");
  }
  if (!window.jspdf) {
    await loadScriptWithTimeout("https://cdnjs.cloudflare.com/ajax/libs/jspdf/2.5.1/jspdf.umd.min.js");
  }
  if (!window.html2canvas || !window.jspdf) {
    throw new Error("As bibliotecas de geração de PDF não ficaram disponíveis neste ambiente.");
  }
}

async function generateProposalPdf(pageEls, filename) {
  await ensurePdfLibs();
  const { jsPDF } = window.jspdf;
  const doc = new jsPDF({ unit: "mm", format: "a4", compress: true });
  const pageWidth = doc.internal.pageSize.getWidth();
  const pageHeight = doc.internal.pageSize.getHeight();

  for (let i = 0; i < pageEls.length; i++) {
    const el = pageEls[i];
    if (!el) continue;
    const canvas = await window.html2canvas(el, {
      scale: 2,
      backgroundColor: "#ffffff",
      useCORS: true,
      windowWidth: Math.max(el.scrollWidth, 1200),
      windowHeight: el.scrollHeight,
    });
    const imgData = canvas.toDataURL("image/jpeg", 0.95);
    const imgHeight = Math.min((canvas.height * pageWidth) / canvas.width, pageHeight);
    if (i > 0) doc.addPage();
    doc.addImage(imgData, "JPEG", 0, 0, pageWidth, imgHeight);
  }

  doc.save(filename);
}

