function ProposalsTable({ proposals, protocols, onView, onEdit, onDuplicate, onPdf, onDelete, compact }) {
  if (!proposals.length) {
    return <p className="cc-empty">Nenhuma proposta encontrada ainda.</p>;
  }
  return (
    <table className="cc-table">
      <thead>
        <tr>
          <th>Paciente</th>
          <th>Protocolo</th>
          <th>Data</th>
          <th>Status</th>
          {!compact && <th className="cc-actions-col">Ações</th>}
        </tr>
      </thead>
      <tbody>
        {proposals.map((p) => {
          const protocolName = protocols?.find((pr) => pr.id === p.protocolId)?.name || "—";
          return (
            <tr key={p.id}>
              <td>{p.patientName}</td>
              <td>{protocolName}</td>
              <td>{p.date?.split("-").reverse().join(".")}</td>
              <td><Badge status={p.status} /></td>
              {!compact && (
                <td>
                  <div className="cc-row-actions">
                    <IconBtn icon={Eye} title="Visualizar" onClick={() => onView(p)} />
                    <IconBtn icon={Pencil} title="Editar" onClick={() => onEdit(p)} />
                    <IconBtn icon={Copy} title="Duplicar" onClick={() => onDuplicate(p)} />
                    <IconBtn icon={Printer} title="Gerar PDF" onClick={() => onPdf(p)} />
                    <IconBtn icon={Trash2} title="Excluir" tone="danger" onClick={() => onDelete(p)} />
                  </div>
                </td>
              )}
            </tr>
          );
        })}
      </tbody>
    </table>
  );
}

/* ---------------------------------------------------------------
   PROPOSALS LIST VIEW
--------------------------------------------------------------- */
function ProposalsListView({ proposals, protocols, startNewProposal, onView, onEdit, onDuplicate, onPdf, onDelete }) {
  const [query, setQuery] = useState("");
  const [protocolFilter, setProtocolFilter] = useState("");
  const [statusFilter, setStatusFilter] = useState("");

  const filtered = proposals.filter((p) => {
    const matchesQuery = p.patientName.toLowerCase().includes(query.toLowerCase());
    const matchesProtocol = !protocolFilter || p.protocolId === protocolFilter;
    const matchesStatus = !statusFilter || p.status === statusFilter;
    return matchesQuery && matchesProtocol && matchesStatus;
  });

  return (
    <div className="cc-page">
      <header className="cc-page-head">
        <div>
          <h1 className="cc-h1">Propostas</h1>
          <p className="cc-sub">Gerencie e acompanhe as propostas de tratamento da clínica.</p>
        </div>
        <Btn icon={PlusCircle} onClick={startNewProposal}>Nova proposta</Btn>
      </header>

      <div className="cc-toolbar">
        <div className="cc-search">
          <Search size={15} strokeWidth={1.6} />
          <input placeholder="Buscar por nome da paciente…" value={query} onChange={(e) => setQuery(e.target.value)} />
        </div>
        <Select value={protocolFilter} onChange={(e) => setProtocolFilter(e.target.value)}>
          <option value="">Todos os protocolos</option>
          {protocols.map((pr) => <option key={pr.id} value={pr.id}>{pr.name}</option>)}
        </Select>
        <Select value={statusFilter} onChange={(e) => setStatusFilter(e.target.value)}>
          <option value="">Todos os status</option>
          {["Rascunho", "Proposta criada", "Enviada", "Fechada"].map((s) => <option key={s} value={s}>{s}</option>)}
        </Select>
      </div>

      <div className="cc-panel">
        <ProposalsTable
          proposals={filtered}
          protocols={protocols}
          onView={onView}
          onEdit={onEdit}
          onDuplicate={onDuplicate}
          onPdf={onPdf}
          onDelete={onDelete}
        />
      </div>
    </div>
  );
}

