const STEPS = ["Paciente", "Protocolo", "Tratamento", "Investimento", "Finalizar"];

function WizardProgress({ step }) {
  const roman = ["I", "II", "III", "IV", "V"];
  return (
    <div className="cc-wizard-progress">
      {STEPS.map((label, i) => (
        <div key={label} className={`cc-wizard-step ${i === step ? "active" : ""} ${i < step ? "done" : ""}`}>
          <span className="cc-wizard-roman">{roman[i]}</span>
          <span className="cc-wizard-label">{label}</span>
          {i < STEPS.length - 1 && <span className="cc-wizard-thread" />}
        </div>
      ))}
    </div>
  );
}

function NewProposalWizard({ draft, setDraft, procedures, protocols, onCancel, onFinish }) {
  const [step, setStep] = useState(0);

  const protocol = protocols.find((p) => p.id === draft.protocolId);

  function selectProtocol(protocolId) {
    const p = protocols.find((pp) => pp.id === protocolId);
    setDraft((d) => ({ ...d, protocolId, phases: cloneProtocolPhases(p) }));
  }

  function updatePhase(phaseId, patch) {
    setDraft((d) => ({
      ...d,
      phases: d.phases.map((ph) => (ph.id === phaseId ? { ...ph, ...patch } : ph)),
    }));
  }

  function addPhase() {
    setDraft((d) => ({
      ...d,
      phases: [...d.phases, { id: uid("ph"), name: "Nova fase", whatItDoes: "", indications: "", expectedResult: "", items: [] }],
    }));
  }
  function removePhase(phaseId) {
    setDraft((d) => ({ ...d, phases: d.phases.filter((ph) => ph.id !== phaseId) }));
  }
  function movePhase(idx, dir) {
    setDraft((d) => {
      const arr = [...d.phases];
      const target = idx + dir;
      if (target < 0 || target >= arr.length) return d;
      [arr[idx], arr[target]] = [arr[target], arr[idx]];
      return { ...d, phases: arr };
    });
  }

  function addItem(phaseId) {
    const firstActive = procedures.find((p) => p.active);
    if (!firstActive) return;
    updatePhase(phaseId, {
      items: [
        ...draft.phases.find((p) => p.id === phaseId).items,
        { id: uid("it"), procedureId: firstActive.id, qty: "1", unit: firstActive.unit, planInicial: true, planAvancado: true },
      ],
    });
  }
  function updateItem(phaseId, itemId, patch) {
    const phase = draft.phases.find((p) => p.id === phaseId);
    updatePhase(phaseId, {
      items: phase.items.map((it) => (it.id === itemId ? { ...it, ...patch } : it)),
    });
  }
  function removeItem(phaseId, itemId) {
    const phase = draft.phases.find((p) => p.id === phaseId);
    updatePhase(phaseId, { items: phase.items.filter((it) => it.id !== itemId) });
  }

  const canNext = () => {
    if (step === 0) return draft.patientName.trim().length > 0;
    if (step === 1) return !!draft.protocolId;
    return true;
  };

  return (
    <div className="cc-page cc-wizard">
      <header className="cc-page-head">
        <div>
          <h1 className="cc-h1">Nova proposta</h1>
          <p className="cc-sub">Monte a proposta em poucos passos.</p>
        </div>
        <button className="cc-link" onClick={onCancel}><ArrowLeft size={14} /> Cancelar</button>
      </header>

      <WizardProgress step={step} />

      <div className="cc-panel cc-wizard-panel">
        {step === 0 && (
          <div className="cc-form-grid">
            <Field label="Nome completo da paciente" required>
              <Input
                autoFocus
                value={draft.patientName}
                onChange={(e) => setDraft((d) => ({ ...d, patientName: e.target.value }))}
                placeholder="Ex.: Camila Stefani Gomes de Lima"
              />
            </Field>
            <Field label="Data da proposta">
              <Input type="date" value={draft.date} onChange={(e) => setDraft((d) => ({ ...d, date: e.target.value }))} />
            </Field>
          </div>
        )}

        {step === 1 && (
          <div className="cc-form-grid">
            <Field label="Selecione o protocolo" required>
              <div className="cc-protocol-grid">
                {protocols.filter((p) => p.active).map((p) => (
                  <button
                    key={p.id}
                    className={`cc-protocol-card ${draft.protocolId === p.id ? "active" : ""}`}
                    onClick={() => selectProtocol(p.id)}
                    type="button"
                  >
                    <span className="cc-protocol-name">{p.name}</span>
                    <span className="cc-protocol-phases">{p.phases.length} fase(s) pré-configurada(s)</span>
                    {draft.protocolId === p.id && <Check size={16} className="cc-protocol-check" />}
                  </button>
                ))}
              </div>
            </Field>
          </div>
        )}

        {step === 2 && (
          <div className="cc-phases-editor">
            {draft.phases.map((phase, idx) => (
              <div className="cc-phase-block" key={phase.id}>
                <div className="cc-phase-block-head">
                  <GripVertical size={15} className="cc-grip" />
                  <input
                    className="cc-phase-title-input"
                    value={phase.name}
                    onChange={(e) => updatePhase(phase.id, { name: e.target.value })}
                  />
                  <div className="cc-phase-block-actions">
                    <IconBtn icon={ChevronLeft} title="Mover para cima" onClick={() => movePhase(idx, -1)} />
                    <IconBtn icon={ChevronRight} title="Mover para baixo" onClick={() => movePhase(idx, 1)} />
                    <IconBtn icon={Trash2} tone="danger" title="Remover fase" onClick={() => removePhase(phase.id)} />
                  </div>
                </div>

                <div className="cc-phase-items">
                  <span className="cc-field-label">Procedimentos</span>
                  {phase.items.map((item) => (
                    <div className="cc-item-row" key={item.id}>
                      <Select
                        value={item.procedureId}
                        onChange={(e) => {
                          const proc = procedures.find((p) => p.id === e.target.value);
                          updateItem(phase.id, item.id, { procedureId: e.target.value, unit: proc ? proc.unit : item.unit });
                        }}
                      >
                        {procedures.filter((p) => p.active || p.id === item.procedureId).map((p) => (
                          <option key={p.id} value={p.id}>{p.name}{!p.active ? " (inativo)" : ""}</option>
                        ))}
                      </Select>
                      <Input
                        className="cc-item-qty"
                        value={item.qty}
                        onChange={(e) => updateItem(phase.id, item.id, { qty: e.target.value })}
                        placeholder="Qtd. ex: 4–8"
                      />
                      <Input
                        className="cc-item-unit"
                        value={item.unit}
                        onChange={(e) => updateItem(phase.id, item.id, { unit: e.target.value })}
                        placeholder="unidade"
                      />
                      <IconBtn icon={Trash2} tone="danger" title="Remover" onClick={() => removeItem(phase.id, item.id)} />
                    </div>
                  ))}
                  <button className="cc-add-inline" onClick={() => addItem(phase.id)} type="button">
                    <Plus size={13} /> Adicionar procedimento
                  </button>
                </div>

                <div className="cc-phase-texts">
                  <Field label="O que essa fase faz">
                    <Textarea rows={2} value={phase.whatItDoes} onChange={(e) => updatePhase(phase.id, { whatItDoes: e.target.value })} />
                  </Field>
                  <Field label="Resultado esperado">
                    <Textarea rows={2} value={phase.expectedResult} onChange={(e) => updatePhase(phase.id, { expectedResult: e.target.value })} />
                  </Field>
                </div>
              </div>
            ))}
            <button className="cc-add-block" onClick={addPhase} type="button">
              <Plus size={14} /> Adicionar nova fase
            </button>
          </div>
        )}

        {step === 3 && (
          <InvestmentStep draft={draft} setDraft={setDraft} procedures={procedures} />
        )}

        {step === 4 && (
          <div className="cc-finish-step">
            <p className="cc-finish-lead">Tudo pronto. Revise um resumo rápido antes de continuar para a pré-visualização.</p>
            <div className="cc-finish-summary">
              <div><span>Paciente</span><strong>{draft.patientName || "—"}</strong></div>
              <div><span>Protocolo</span><strong>{protocol?.name || "—"}</strong></div>
              <div><span>Fases</span><strong>{draft.phases.length}</strong></div>
              <div><span>Plano Inicial</span><strong>{money(computePlanTotal(draft, procedures, "planInicial"))}</strong></div>
              <div><span>Plano Avançado</span><strong>{money(computePlanTotal(draft, procedures, "planAvancado"))}</strong></div>
            </div>
          </div>
        )}
      </div>

      <div className="cc-wizard-nav">
        <Btn variant="ghost" onClick={() => (step === 0 ? onCancel() : setStep((s) => s - 1))}>
          {step === 0 ? "Cancelar" : "Voltar"}
        </Btn>
        {step < STEPS.length - 1 ? (
          <Btn onClick={() => canNext() && setStep((s) => s + 1)} disabled={!canNext()}>Continuar</Btn>
        ) : (
          <Btn onClick={onFinish}>Pré-visualizar proposta</Btn>
        )}
      </div>
    </div>
  );
}

function computePlanTotal(draft, procedures, planKey) {
  let total = 0;
  for (const phase of draft.phases) {
    for (const item of phase.items) {
      if (!item[planKey]) continue;
      const proc = procedures.find((p) => p.id === item.procedureId);
      if (!proc) continue;
      total += proc.price * qtyForPlan(item.qty, planKey);
    }
  }
  return total;
}

function updatePlanPayment(setDraft, planKey, patch) {
  setDraft((d) => ({
    ...d,
    planPayments: {
      ...d.planPayments,
      [planKey]: { ...d.planPayments[planKey], ...patch },
    },
  }));
}

function PlanPaymentLine({ total, payment }) {
  if (payment.mode === "avista") return <span>À vista: {money(total)}</span>;
  if (payment.mode === "personalizado") return <span>{payment.note || "Condição personalizada a definir"}</span>;
  const installments = Math.max(1, payment.installments || 1);
  return <span>{installments}x de {money(total / installments)}</span>;
}

function PlanConfigCard({ label, planKey, draft, setDraft, procedures }) {
  const total = computePlanTotal(draft, procedures, planKey);
  const payment = draft.planPayments[planKey];
  const includedItems = draft.phases.flatMap((ph) =>
    ph.items.filter((it) => it[planKey]).map((it) => ({ ...it, phaseName: ph.name }))
  );

  return (
    <div className="cc-plan-card">
      <div className="cc-plan-card-head">
        <h3>{label}</h3>
        <span className="cc-plan-card-total">{money(total)}</span>
      </div>

      <ul className="cc-plan-card-items">
        {includedItems.length === 0 && <li className="cc-plan-card-empty">Nenhum procedimento incluído neste plano.</li>}
        {includedItems.map((item) => {
          const proc = procedures.find((p) => p.id === item.procedureId);
          if (!proc) return null;
          return <li key={item.id}>{proc.name} <span>({formatQtyNumber(qtyForPlan(item.qty, planKey))} {item.unit})</span></li>;
        })}
      </ul>

      <div className="cc-plan-payment">
        <div className="cc-payment-grid cc-payment-grid-3">
          {[
            { key: "parcelado", label: "Parcelado" },
            { key: "avista", label: "À vista" },
            { key: "personalizado", label: "Personalizado" },
          ].map((opt) => (
            <button
              key={opt.key}
              type="button"
              className={`cc-payment-card ${payment.mode === opt.key ? "active" : ""}`}
              onClick={() => updatePlanPayment(setDraft, planKey, { mode: opt.key })}
            >
              {opt.label}
            </button>
          ))}
        </div>

        {payment.mode === "parcelado" && (
          <Field label="Número de parcelas">
            <Input
              type="number"
              min="1"
              value={payment.installments}
              onChange={(e) => updatePlanPayment(setDraft, planKey, { installments: parseInt(e.target.value) || 1 })}
            />
          </Field>
        )}
        {payment.mode === "personalizado" && (
          <Field label="Observação">
            <Textarea rows={2} value={payment.note} onChange={(e) => updatePlanPayment(setDraft, planKey, { note: e.target.value })} />
          </Field>
        )}

        <p className="cc-plan-payment-preview">
          Como vai aparecer no PDF: <strong><PlanPaymentLine total={total} payment={payment} /></strong>
        </p>
      </div>
    </div>
  );
}

function InvestmentStep({ draft, setDraft, procedures }) {
  function toggleItemPlan(phaseId, itemId, planKey) {
    setDraft((d) => ({
      ...d,
      phases: d.phases.map((ph) =>
        ph.id !== phaseId ? ph : {
          ...ph,
          items: ph.items.map((it) => (it.id === itemId ? { ...it, [planKey]: !it[planKey] } : it)),
        }
      ),
    }));
  }

  return (
    <div className="cc-investment-step">
      <p className="cc-finish-lead">Marque em quais planos cada procedimento entra. O valor de cada plano é somado automaticamente.</p>

      <table className="cc-table cc-invest-table">
        <thead>
          <tr>
            <th>Procedimento</th>
            <th>Quantidade</th>
            <th>Unidade</th>
            <th>Valor unitário (referência)</th>
            <th className="cc-plan-col">Inicial</th>
            <th className="cc-plan-col">Avançado</th>
          </tr>
        </thead>
        <tbody>
          {draft.phases.map((phase) => (
            <React.Fragment key={phase.id}>
              <tr className="cc-invest-phase-row"><td colSpan={6}>{phase.name}</td></tr>
              {phase.items.map((item) => {
                const proc = procedures.find((p) => p.id === item.procedureId);
                if (!proc) return null;
                return (
                  <tr key={item.id}>
                    <td>{proc.name}</td>
                    <td>{item.qty}</td>
                    <td>{item.unit}</td>
                    <td>{money(proc.price)}</td>
                    <td className="cc-plan-col">
                      <input type="checkbox" checked={!!item.planInicial} onChange={() => toggleItemPlan(phase.id, item.id, "planInicial")} />
                    </td>
                    <td className="cc-plan-col">
                      <input type="checkbox" checked={!!item.planAvancado} onChange={() => toggleItemPlan(phase.id, item.id, "planAvancado")} />
                    </td>
                  </tr>
                );
              })}
            </React.Fragment>
          ))}
        </tbody>
      </table>

      <div className="cc-plan-cards">
        <PlanConfigCard label="Plano Inicial" planKey="planInicial" draft={draft} setDraft={setDraft} procedures={procedures} />
        <PlanConfigCard label="Plano Avançado" planKey="planAvancado" draft={draft} setDraft={setDraft} procedures={procedures} />
      </div>
    </div>
  );
}

/* ---------------------------------------------------------------
   PREVIEW / PDF VIEW
--------------------------------------------------------------- */
function PreviewView({ proposal, protocols, procedures, clinic, onBack, editable }) {
  const protocol = protocols.find((p) => p.id === proposal.protocolId);
  const page1Ref = useRef(null);
  const page2Ref = useRef(null);
  const [generating, setGenerating] = useState(false);
  const [pdfError, setPdfError] = useState("");

  async function handleDownloadPdf() {
    setGenerating(true);
    setPdfError("");
    try {
      const safeName = (proposal.patientName || "proposta").trim().replace(/\s+/g, "_");
      const filename = `Proposta_${safeName}_${proposal.date || ""}.pdf`;
      await generateProposalPdf([page1Ref.current, page2Ref.current], filename);
    } catch (err) {
      console.error("Erro ao gerar PDF:", err);
      setPdfError(`Não foi possível gerar o PDF neste ambiente (${err.message || "erro desconhecido"}). Use "Imprimir" como alternativa, ou teste novamente após publicar o site.`);
    } finally {
      setGenerating(false);
    }
  }

  return (
    <div className="cc-page cc-preview-page">
      <header className="cc-page-head cc-no-print">
        <div>
          <h1 className="cc-h1">Pré-visualização da proposta</h1>
          <p className="cc-sub">Confira antes de baixar o PDF em duas páginas, pronto para impressão.</p>
        </div>
        <div className="cc-preview-actions">
          <Btn variant="ghost" icon={ArrowLeft} onClick={onBack}>Voltar e editar</Btn>
          <Btn variant="ghost" icon={Printer} onClick={() => window.print()}>Imprimir</Btn>
          <Btn icon={generating ? Loader2 : Download} onClick={handleDownloadPdf} disabled={generating} className={generating ? "cc-btn-loading" : ""}>
            {generating ? "Gerando PDF…" : "Baixar PDF"}
          </Btn>
        </div>
      </header>
      {pdfError && <p className="cc-error cc-no-print">{pdfError}</p>}

      <div className="cc-print-area">
        {/* PAGE 1 */}
        <div className="cc-paper" ref={page1Ref}>
          <div className="cc-paper-header">
            <img src={LOGO_DARK} alt={clinic.name} />
          </div>
          <h2 className="cc-paper-title">Cronograma de Tratamento</h2>
          <div className="cc-paper-meta">
            <span><strong>Nome paciente:</strong> {proposal.patientName}</span>
            <span><strong>Data:</strong> {proposal.date?.split("-").reverse().join(".")}</span>
          </div>

          <h3 className="cc-paper-protocol">{protocol?.name}</h3>

          {proposal.phases.map((phase, i) => (
            <div className="cc-paper-phase" key={phase.id}>
              <h4>FASE {i + 1} — {phase.name.toUpperCase()}</h4>
              <div className="cc-paper-phase-cols">
                <div>
                  <span className="cc-paper-label">Indicações para você</span>
                  <ul>
                    {phase.items.map((item) => {
                      const proc = procedures.find((p) => p.id === item.procedureId);
                      return <li key={item.id}>{proc?.name} ({item.qty} {item.unit})</li>;
                    })}
                  </ul>
                  {phase.indications && <p className="cc-paper-text">{phase.indications}</p>}
                </div>
                <div>
                  <span className="cc-paper-label">O que essa fase faz</span>
                  <p className="cc-paper-text">{phase.whatItDoes}</p>
                </div>
                <div>
                  <span className="cc-paper-label">Resultado esperado</span>
                  <p className="cc-paper-text">{phase.expectedResult}</p>
                </div>
              </div>
            </div>
          ))}

          <div className="cc-paper-footer-block">
            <p className="cc-paper-validity">{clinic.validityText}</p>
            <div className="cc-paper-footer">
              <img src={LOGO_DARK} alt={clinic.name} className="cc-paper-footer-logo" />
              <div className="cc-paper-footer-contact">
                <span>{clinic.instagram}</span>
                <span>{clinic.phone}</span>
                <span>{clinic.email}</span>
                <span>{clinic.address}</span>
              </div>
            </div>
          </div>
        </div>

        {/* PAGE 2 */}
        <div className="cc-paper cc-page-break" ref={page2Ref}>
          <div className="cc-paper-header">
            <img src={LOGO_DARK} alt={clinic.name} />
          </div>
          <h2 className="cc-paper-title">Cronograma de Tratamento</h2>
          <div className="cc-paper-meta">
            <span><strong>Nome paciente:</strong> {proposal.patientName}</span>
            <span><strong>Data:</strong> {proposal.date?.split("-").reverse().join(".")}</span>
            <span><strong>Protocolo:</strong> {protocol?.name}</span>
          </div>

          <h3 className="cc-paper-protocol">Planos de tratamento</h3>

          <div className="cc-paper-plans">
            {[
              { key: "planInicial", label: "Plano Inicial" },
              { key: "planAvancado", label: "Plano Avançado" },
            ].map(({ key, label }) => {
              const payment = proposal.planPayments?.[key] || { mode: "parcelado", installments: 10, note: "" };
              const total = computePlanTotal(proposal, procedures, key);
              const items = proposal.phases.flatMap((ph) => ph.items.filter((it) => it[key]));
              return (
                <div className="cc-paper-plan" key={key}>
                  <h5>{label}</h5>
                  {items.length === 0 ? (
                    <p className="cc-paper-text cc-paper-plan-empty">Nenhum procedimento incluído.</p>
                  ) : (
                    <ul>
                      {items.map((item) => {
                        const proc = procedures.find((p) => p.id === item.procedureId);
                        if (!proc) return null;
                        return <li key={item.id}>{proc.name} <span>({formatQtyNumber(qtyForPlan(item.qty, key))} {item.unit})</span></li>;
                      })}
                    </ul>
                  )}
                  <p className="cc-paper-plan-total">
                    <PlanPaymentLine total={total} payment={payment} />
                  </p>
                </div>
              );
            })}
          </div>

          <div className="cc-paper-footer-block">
            <p className="cc-paper-validity">{clinic.validityText}</p>
            <div className="cc-paper-footer">
              <img src={LOGO_DARK} alt={clinic.name} className="cc-paper-footer-logo" />
              <div className="cc-paper-footer-contact">
                <span>{clinic.instagram}</span>
                <span>{clinic.phone}</span>
                <span>{clinic.email}</span>
                <span>{clinic.address}</span>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

/* ---------------------------------------------------------------
   PROCEDURES VIEW
--------------------------------------------------------------- */
function ProceduresView({ procedures, setProcedures }) {
  const [editing, setEditing] = useState(null); // procedure object or "new"

  function save(proc) {
    setProcedures((list) => {
      if (proc.id) return list.map((p) => (p.id === proc.id ? proc : p));
      return [...list, { ...proc, id: uid("proc") }];
    });
    setEditing(null);
  }
  function toggleActive(proc) {
    setProcedures((list) => list.map((p) => (p.id === proc.id ? { ...p, active: !p.active } : p)));
  }

  return (
    <div className="cc-page">
      <header className="cc-page-head">
        <div>
          <h1 className="cc-h1">Procedimentos</h1>
          <p className="cc-sub">Base de procedimentos e preços usada automaticamente nas propostas.</p>
        </div>
        <Btn icon={PlusCircle} onClick={() => setEditing("new")}>Novo procedimento</Btn>
      </header>

      <div className="cc-panel">
        <table className="cc-table">
          <thead>
            <tr><th>Nome</th><th>Unidade</th><th>Valor unitário</th><th>Parcelamento</th><th>Status</th><th className="cc-actions-col">Ações</th></tr>
          </thead>
          <tbody>
            {procedures.map((p) => (
              <tr key={p.id} className={!p.active ? "cc-row-inactive" : ""}>
                <td>{p.name}</td>
                <td>{p.unit}</td>
                <td>{money(p.price)}</td>
                <td>{p.installments}x</td>
                <td><span className={`cc-badge ${p.active ? "cc-badge-done" : "cc-badge-muted"}`}>{p.active ? "Ativo" : "Inativo"}</span></td>
                <td>
                  <div className="cc-row-actions">
                    <IconBtn icon={Pencil} title="Editar" onClick={() => setEditing(p)} />
                    <IconBtn icon={p.active ? X : Check} title={p.active ? "Desativar" : "Ativar"} onClick={() => toggleActive(p)} />
                  </div>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {editing && (
        <ProcedureModal
          procedure={editing === "new" ? null : editing}
          onClose={() => setEditing(null)}
          onSave={save}
        />
      )}
    </div>
  );
}

function ProcedureModal({ procedure, onClose, onSave }) {
  const [form, setForm] = useState(
    procedure || { name: "", unit: "sessão", price: 0, installments: 10, active: true, description: "" }
  );
  return (
    <Modal title={procedure ? "Editar procedimento" : "Novo procedimento"} onClose={onClose}>
      <div className="cc-form-grid">
        <Field label="Nome" required>
          <Input value={form.name} onChange={(e) => setForm((f) => ({ ...f, name: e.target.value }))} />
        </Field>
        <Field label="Descrição">
          <Textarea rows={2} value={form.description || ""} onChange={(e) => setForm((f) => ({ ...f, description: e.target.value }))} />
        </Field>
        <div className="cc-form-row">
          <Field label="Unidade de cobrança">
            <Input value={form.unit} onChange={(e) => setForm((f) => ({ ...f, unit: e.target.value }))} placeholder="sessão, caixa…" />
          </Field>
          <Field label="Valor unitário (R$)">
            <Input type="number" min="0" step="0.01" value={form.price} onChange={(e) => setForm((f) => ({ ...f, price: parseFloat(e.target.value) || 0 }))} />
          </Field>
        </div>
        <div className="cc-form-row">
          <Field label="Parcelamento padrão">
            <Input type="number" min="1" value={form.installments} onChange={(e) => setForm((f) => ({ ...f, installments: parseInt(e.target.value) || 1 }))} />
          </Field>
          <Field label="Status">
            <Select value={form.active ? "1" : "0"} onChange={(e) => setForm((f) => ({ ...f, active: e.target.value === "1" }))}>
              <option value="1">Ativo</option>
              <option value="0">Inativo</option>
            </Select>
          </Field>
        </div>
      </div>
      <div className="cc-modal-actions">
        <Btn variant="ghost" onClick={onClose}>Cancelar</Btn>
        <Btn onClick={() => onSave(form)} disabled={!form.name.trim()}>Salvar</Btn>
      </div>
    </Modal>
  );
}

/* ---------------------------------------------------------------
   PROTOCOLS VIEW
--------------------------------------------------------------- */
function ProtocolsView({ protocols, setProtocols, procedures }) {
  const [editingId, setEditingId] = useState(null);

  function addProtocol() {
    const p = { id: uid("prot"), name: "Novo protocolo", active: true, phases: [] };
    setProtocols((list) => [...list, p]);
    setEditingId(p.id);
  }
  function toggleActive(id) {
    setProtocols((list) => list.map((p) => (p.id === id ? { ...p, active: !p.active } : p)));
  }
  function updateProtocol(id, patch) {
    setProtocols((list) => list.map((p) => (p.id === id ? { ...p, ...patch } : p)));
  }

  const editing = protocols.find((p) => p.id === editingId);

  return (
    <div className="cc-page">
      <header className="cc-page-head">
        <div>
          <h1 className="cc-h1">Protocolos</h1>
          <p className="cc-sub">Modelos de tratamento com fases e procedimentos pré-configurados.</p>
        </div>
        <Btn icon={PlusCircle} onClick={addProtocol}>Novo protocolo</Btn>
      </header>

      <div className="cc-protocol-list">
        {protocols.map((p) => (
          <div key={p.id} className={`cc-protocol-row ${!p.active ? "cc-row-inactive" : ""}`}>
            <div className="cc-protocol-row-main" onClick={() => setEditingId(p.id === editingId ? null : p.id)}>
              <span className="cc-protocol-row-name">{p.name}</span>
              <span className="cc-protocol-row-meta">{p.phases.length} fase(s)</span>
            </div>
            <div className="cc-row-actions">
              <span className={`cc-badge ${p.active ? "cc-badge-done" : "cc-badge-muted"}`}>{p.active ? "Ativo" : "Inativo"}</span>
              <IconBtn icon={Pencil} title="Editar" onClick={() => setEditingId(p.id)} />
              <IconBtn icon={p.active ? X : Check} title={p.active ? "Desativar" : "Ativar"} onClick={() => toggleActive(p.id)} />
            </div>
          </div>
        ))}
      </div>

      {editing && (
        <ProtocolEditor
          protocol={editing}
          procedures={procedures}
          onChange={(patch) => updateProtocol(editing.id, patch)}
          onClose={() => setEditingId(null)}
        />
      )}
    </div>
  );
}

function ProtocolEditor({ protocol, procedures, onChange, onClose }) {
  function addPhase() {
    onChange({ phases: [...protocol.phases, { id: uid("ph"), name: "Nova fase", whatItDoes: "", indications: "", expectedResult: "", items: [] }] });
  }
  function updatePhase(id, patch) {
    onChange({ phases: protocol.phases.map((ph) => (ph.id === id ? { ...ph, ...patch } : ph)) });
  }
  function removePhase(id) {
    onChange({ phases: protocol.phases.filter((ph) => ph.id !== id) });
  }
  function addItem(phaseId) {
    const first = procedures.find((p) => p.active);
    if (!first) return;
    const phase = protocol.phases.find((p) => p.id === phaseId);
    updatePhase(phaseId, { items: [...phase.items, { id: uid("it"), procedureId: first.id, qty: "1", unit: first.unit, planInicial: true, planAvancado: true }] });
  }
  function updateItem(phaseId, itemId, patch) {
    const phase = protocol.phases.find((p) => p.id === phaseId);
    updatePhase(phaseId, { items: phase.items.map((it) => (it.id === itemId ? { ...it, ...patch } : it)) });
  }
  function removeItem(phaseId, itemId) {
    const phase = protocol.phases.find((p) => p.id === phaseId);
    updatePhase(phaseId, { items: phase.items.filter((it) => it.id !== itemId) });
  }

  return (
    <Modal title={`Editar protocolo`} onClose={onClose} width={720}>
      <Field label="Nome do protocolo">
        <Input value={protocol.name} onChange={(e) => onChange({ name: e.target.value })} />
      </Field>

      <div className="cc-phases-editor cc-phases-editor-modal">
        {protocol.phases.map((phase) => (
          <div className="cc-phase-block" key={phase.id}>
            <div className="cc-phase-block-head">
              <input className="cc-phase-title-input" value={phase.name} onChange={(e) => updatePhase(phase.id, { name: e.target.value })} />
              <IconBtn icon={Trash2} tone="danger" title="Remover fase" onClick={() => removePhase(phase.id)} />
            </div>
            <div className="cc-phase-items">
              {phase.items.map((item) => (
                <div className="cc-item-row" key={item.id}>
                  <Select value={item.procedureId} onChange={(e) => {
                    const proc = procedures.find((p) => p.id === e.target.value);
                    updateItem(phase.id, item.id, { procedureId: e.target.value, unit: proc ? proc.unit : item.unit });
                  }}>
                    {procedures.filter((p) => p.active || p.id === item.procedureId).map((p) => (
                      <option key={p.id} value={p.id}>{p.name}</option>
                    ))}
                  </Select>
                  <Input className="cc-item-qty" value={item.qty} onChange={(e) => updateItem(phase.id, item.id, { qty: e.target.value })} />
                  <Input className="cc-item-unit" value={item.unit} onChange={(e) => updateItem(phase.id, item.id, { unit: e.target.value })} />
                  <IconBtn icon={Trash2} tone="danger" onClick={() => removeItem(phase.id, item.id)} />
                </div>
              ))}
              <button className="cc-add-inline" onClick={() => addItem(phase.id)} type="button"><Plus size={13} /> Adicionar procedimento</button>
            </div>
            <div className="cc-phase-texts">
              <Field label="O que essa fase faz">
                <Textarea rows={2} value={phase.whatItDoes} onChange={(e) => updatePhase(phase.id, { whatItDoes: e.target.value })} />
              </Field>
              <Field label="Indicações para você">
                <Textarea rows={2} value={phase.indications} onChange={(e) => updatePhase(phase.id, { indications: e.target.value })} />
              </Field>
              <Field label="Resultado esperado">
                <Textarea rows={2} value={phase.expectedResult} onChange={(e) => updatePhase(phase.id, { expectedResult: e.target.value })} />
              </Field>
            </div>
          </div>
        ))}
        <button className="cc-add-block" onClick={addPhase} type="button"><Plus size={14} /> Adicionar fase</button>
      </div>

      <div className="cc-modal-actions">
        <Btn onClick={onClose}>Concluído</Btn>
      </div>
    </Modal>
  );
}

/* ---------------------------------------------------------------
   PATIENTS VIEW
--------------------------------------------------------------- */
function PatientsView({ proposals, protocols, onView }) {
  const [selected, setSelected] = useState(null);

  const patients = useMemo(() => {
    const map = new Map();
    for (const p of proposals) {
      const key = p.patientName.trim().toLowerCase();
      if (!map.has(key)) map.set(key, { name: p.patientName, proposals: [] });
      map.get(key).proposals.push(p);
    }
    return [...map.values()].map((pt) => {
      const sorted = [...pt.proposals].sort((a, b) => (a.date < b.date ? 1 : -1));
      return {
        ...pt,
        count: pt.proposals.length,
        lastDate: sorted[0]?.date,
        lastProtocol: protocols.find((pr) => pr.id === sorted[0]?.protocolId)?.name,
        sorted,
      };
    });
  }, [proposals, protocols]);

  if (selected) {
    return (
      <div className="cc-page">
        <header className="cc-page-head">
          <div>
            <h1 className="cc-h1">{selected.name}</h1>
            <p className="cc-sub">Histórico de propostas.</p>
          </div>
          <button className="cc-link" onClick={() => setSelected(null)}><ArrowLeft size={14} /> Voltar</button>
        </header>
        <div className="cc-panel">
          <ProposalsTable proposals={selected.sorted} protocols={protocols} onView={onView}
            onEdit={() => {}} onDuplicate={() => {}} onPdf={onView} onDelete={() => {}} />
        </div>
      </div>
    );
  }

  return (
    <div className="cc-page">
      <header className="cc-page-head">
        <div>
          <h1 className="cc-h1">Pacientes</h1>
          <p className="cc-sub">Pacientes com propostas registradas.</p>
        </div>
      </header>
      <div className="cc-panel">
        {!patients.length && <p className="cc-empty">Nenhuma paciente cadastrada ainda.</p>}
        {!!patients.length && (
          <table className="cc-table">
            <thead>
              <tr><th>Nome</th><th>Propostas</th><th>Última proposta</th><th>Protocolo mais recente</th></tr>
            </thead>
            <tbody>
              {patients.map((pt) => (
                <tr key={pt.name} className="cc-row-clickable" onClick={() => setSelected(pt)}>
                  <td>{pt.name}</td>
                  <td>{pt.count}</td>
                  <td>{pt.lastDate?.split("-").reverse().join(".")}</td>
                  <td>{pt.lastProtocol || "—"}</td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </div>
    </div>
  );
}

/* ---------------------------------------------------------------
   SETTINGS VIEW
--------------------------------------------------------------- */
function SettingsView({ clinic, setClinic }) {
  const [form, setForm] = useState(clinic);
  const [saved, setSaved] = useState(false);

  function save() {
    setClinic(form);
    setSaved(true);
    setTimeout(() => setSaved(false), 2000);
  }

  return (
    <div className="cc-page">
      <header className="cc-page-head">
        <div>
          <h1 className="cc-h1">Configurações</h1>
          <p className="cc-sub">Dados da clínica usados nas propostas e no PDF.</p>
        </div>
      </header>
      <div className="cc-panel cc-settings-panel">
        <div className="cc-form-grid">
          <Field label="Nome da clínica">
            <Input value={form.name} onChange={(e) => setForm((f) => ({ ...f, name: e.target.value }))} />
          </Field>
          <div className="cc-form-row">
            <Field label="Instagram">
              <Input value={form.instagram} onChange={(e) => setForm((f) => ({ ...f, instagram: e.target.value }))} />
            </Field>
            <Field label="Telefone">
              <Input value={form.phone} onChange={(e) => setForm((f) => ({ ...f, phone: e.target.value }))} />
            </Field>
          </div>
          <div className="cc-form-row">
            <Field label="E-mail">
              <Input value={form.email} onChange={(e) => setForm((f) => ({ ...f, email: e.target.value }))} />
            </Field>
            <Field label="Endereço">
              <Input value={form.address} onChange={(e) => setForm((f) => ({ ...f, address: e.target.value }))} />
            </Field>
          </div>
          <Field label="Texto de validade padrão da proposta">
            <Textarea rows={3} value={form.validityText} onChange={(e) => setForm((f) => ({ ...f, validityText: e.target.value }))} />
          </Field>
        </div>
        <div className="cc-modal-actions">
          {saved && <span className="cc-saved-note">Configurações salvas.</span>}
          <Btn onClick={save}>Salvar alterações</Btn>
        </div>
      </div>
    </div>
  );
}

/* ---------------------------------------------------------------
   ROOT APP
--------------------------------------------------------------- */
export default function ClassyClinicApp() {
  const [user] = useState({ name: "Equipe Classy Clinic", role: "Uso interno" });
  const [view, setView] = useState("dashboard");

  const [procedures, setProcedures] = useState([]);
  const [protocols, setProtocols] = useState([]);
  const [clinic, setClinic] = useState(seedClinic);
  const [proposals, setProposals] = useState([]);

  const [draft, setDraft] = useState(null);
  const [previewing, setPreviewing] = useState(null);
  const [editingProposalId, setEditingProposalId] = useState(null);

  const [loading, setLoading] = useState(true);
  const [loadError, setLoadError] = useState("");
  const ready = useRef(false); // vira true só depois que os dados iniciais chegam do Supabase

  // Carrega tudo do Supabase quando o site abre
  useEffect(() => {
    (async () => {
      try {
        const data = await loadAllData();
        await seedSupabaseIfEmpty(data);
        setProcedures(data.procedures || seedProcedures);
        setProtocols(data.protocols || seedProtocols);
        setClinic(data.clinic || seedClinic);
        setProposals(data.proposals || [seedInitialProposal()]);
      } catch (err) {
        console.error("Erro ao carregar dados iniciais:", err);
        setLoadError(`Não foi possível carregar os dados salvos. Detalhe: ${err.message || err}`);
      } finally {
        setLoading(false);
        ready.current = true;
      }
    })();
  }, []);

  // A partir do momento em que os dados carregam, qualquer alteração
  // nessas listas é automaticamente salva no Supabase.
  useEffect(() => {
    if (!ready.current || !procedures.length) return;
    sb.upsert("procedures", procedures.map(procedureToRow)).catch((err) =>
      console.error("Erro ao salvar procedimentos:", err)
    );
  }, [procedures]);

  useEffect(() => {
    if (!ready.current || !protocols.length) return;
    sb.upsert("protocols", protocols.map(protocolToRow)).catch((err) =>
      console.error("Erro ao salvar protocolos:", err)
    );
  }, [protocols]);

  useEffect(() => {
    if (!ready.current) return;
    sb.upsert("clinic_settings", [clinicToRow(clinic)]).catch((err) =>
      console.error("Erro ao salvar dados da clínica:", err)
    );
  }, [clinic]);

  function startNewProposal() {
    setDraft({ id: null, patientName: "", date: today(), protocolId: "", status: "Rascunho", phases: [], planPayments: defaultPlanPayments() });
    setEditingProposalId(null);
    setView("new-proposal");
  }

  function editProposal(p) {
    setDraft(JSON.parse(JSON.stringify(p)));
    setEditingProposalId(p.id);
    setView("new-proposal");
  }

  function duplicateProposal(p) {
    const copy = JSON.parse(JSON.stringify(p));
    copy.id = uid("prop");
    copy.date = today();
    copy.status = "Rascunho";
    setProposals((list) => [copy, ...list]);
    sb.upsert("proposals", [proposalToRow(copy)]).catch((err) =>
      console.error("Erro ao salvar proposta duplicada:", err)
    );
  }

  function deleteProposal(p) {
    if (window.confirm(`Excluir a proposta de ${p.patientName}?`)) {
      setProposals((list) => list.filter((x) => x.id !== p.id));
      sb.remove("proposals", p.id).catch((err) =>
        console.error("Erro ao excluir proposta:", err)
      );
    }
  }

  function finishWizard() {
    const finalProposal = {
      ...draft,
      id: draft.id || uid("prop"),
      status: draft.status === "Rascunho" ? "Proposta criada" : draft.status,
      createdAt: draft.createdAt || today(),
    };
    setProposals((list) => {
      const exists = list.some((p) => p.id === finalProposal.id);
      return exists ? list.map((p) => (p.id === finalProposal.id ? finalProposal : p)) : [finalProposal, ...list];
    });
    sb.upsert("proposals", [proposalToRow(finalProposal)]).catch((err) =>
      console.error("Erro ao salvar proposta:", err)
    );
    setPreviewing(finalProposal);
    setView("preview");
  }

  function viewProposal(p) {
    setPreviewing(p);
    setView("preview");
  }
  function pdfProposal(p) {
    setPreviewing(p);
    setView("preview");
  }

  if (loading) {
    return (
      <>
        <GlobalStyles />
        <div className="cc-app" style={{ alignItems: "center", justifyContent: "center", display: "flex" }}>
          <div style={{ textAlign: "center", color: "var(--gray-500, #888)" }}>
            <Loader2 size={28} style={{ animation: "cc-spin 0.8s linear infinite" }} />
            <p style={{ marginTop: 12 }}>Carregando dados salvos...</p>
          </div>
        </div>
      </>
    );
  }

  if (loadError) {
    return (
      <>
        <GlobalStyles />
        <div className="cc-app" style={{ alignItems: "center", justifyContent: "center", display: "flex" }}>
          <div style={{ textAlign: "center", maxWidth: 420 }}>
            <p>{loadError}</p>
          </div>
        </div>
      </>
    );
  }

  if (view === "preview" && previewing) {
    return (
      <>
        <GlobalStyles />
        <PreviewView
          proposal={previewing}
          protocols={protocols}
          procedures={procedures}
          clinic={clinic}
          onBack={() => setView(editingProposalId ? "proposals" : "proposals")}
        />
      </>
    );
  }

  return (
    <>
      <GlobalStyles />
      <div className="cc-app">
        <Sidebar view={view} setView={(v) => { if (v === "new-proposal") { startNewProposal(); } else { setView(v); } }} user={user} />
        <main className="cc-main">
          {view === "dashboard" && (
            <DashboardView proposals={proposals} setView={setView} startNewProposal={startNewProposal} user={user} />
          )}
          {view === "proposals" && (
            <ProposalsListView
              proposals={proposals}
              protocols={protocols}
              startNewProposal={startNewProposal}
              onView={viewProposal}
              onEdit={editProposal}
              onDuplicate={duplicateProposal}
              onPdf={pdfProposal}
              onDelete={deleteProposal}
            />
          )}
          {view === "new-proposal" && draft && (
            <NewProposalWizard
              draft={draft}
              setDraft={setDraft}
              procedures={procedures}
              protocols={protocols}
              onCancel={() => setView("proposals")}
              onFinish={finishWizard}
            />
          )}
          {view === "procedures" && <ProceduresView procedures={procedures} setProcedures={setProcedures} />}
          {view === "protocols" && <ProtocolsView protocols={protocols} setProtocols={setProtocols} procedures={procedures} />}
          {view === "patients" && <PatientsView proposals={proposals} protocols={protocols} onView={viewProposal} />}
          {view === "settings" && <SettingsView clinic={clinic} setClinic={setClinic} />}
        </main>
      </div>
    </>
  );
}

